import re
from ascii_tool import rasterize_path_ascii, print_ascii

def decode_text(d):
    pts = rasterize_path_ascii(d)
    if not pts: return ""
    xs = [p[0] for p in pts]
    ys = [p[1] for p in pts]
    min_x, max_x = min(xs), max(xs)
    print(f"Bounds: X=[{min(xs):.1f}, {max(xs):.1f}], Y=[{min(ys):.1f}, {max(ys):.1f}]")
    # print in slices of 120 width
    cur = min_x
    while cur < max_x:
        sub = [p for p in pts if cur - 5 <= p[0] <= cur + 125]
        if sub:
            print(f"--- Slice {cur:.1f} to {cur+120:.1f} ---")
            print_ascii(sub)
        cur += 120

